import{_ as e,o as a,c as o,a2 as n}from"./chunks/framework.DXGs2oJ2.js";const u=JSON.parse('{"title":"Appendix A — Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"en/appendix-a-glossary.md","filePath":"en/appendix-a-glossary.md","lastUpdated":null}'),i={name:"en/appendix-a-glossary.md"};function r(d,t,s,c,l,h){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="appendix-a-—-glossary" tabindex="-1">Appendix A — Glossary <a class="header-anchor" href="#appendix-a-—-glossary" aria-label="Permalink to &quot;Appendix A — Glossary&quot;">​</a></h1><p>This glossary covers only terms that carry a specific meaning in this book. General engineering vocabulary (such as &quot;interface&quot; or &quot;deployment&quot;) is not included. For every English term that appears in the body text, the glossary gives the unified rendering used throughout.</p><table tabindex="0"><thead><tr><th>Term</th><th>English</th><th>Definition</th><th>Confusable with</th></tr></thead><tbody><tr><td>Single-pass ADD-only</td><td>single-pass ADD-only</td><td>Writing only appends new facts; one model call completes the write and never modifies or deletes existing facts</td><td>Not the same as an append-only log: the former still performs structured extraction and typing, the latter stores raw text</td></tr><tr><td>Dual time axis</td><td>dual time axis</td><td>Separating &quot;when the fact held&quot; (<code>observation_date</code>) from &quot;when the system learned it&quot; (write time)</td><td>Not the same as a version chain: a version chain records multiple changes to one entity; the dual time axis records two temporal dimensions of one fact</td></tr><tr><td>Scope</td><td>scope</td><td>The isolation dimension of memory; in this book specifically the four dimensions <code>user_id</code> / <code>agent_id</code> / <code>run_id</code> / <code>app_id</code></td><td>Not the same as namespace: scope is the logical isolation dimension, namespace is the physical carrier</td></tr><tr><td>Namespace</td><td>namespace</td><td>The independent storage unit derived from a scope, corresponding to an independent directory and database file</td><td>Do not mistake a &quot;hard-coded namespace&quot; for &quot;isolated&quot;</td></tr><tr><td>Physical isolation</td><td>physical isolation</td><td>One independent file per scope, rather than a shared table with filter conditions</td><td>Contrasted with logical isolation, whose risk is a missing filter condition</td></tr><tr><td>Hash-chained audit ledger</td><td>hash-chained audit ledger</td><td>Each record contains the SHA-256 hash of the previous record, forming a chain in which tampering can be located</td><td>Not the same as an operation log: a log can be deleted or altered without trace, a hash chain cannot</td></tr><tr><td>Provenance tracing</td><td>provenance tracing</td><td>Following the pointer chain from a high-level conclusion back to the original message, answering &quot;which sentence did this conclusion come from&quot;</td><td>Not the same as log tracing, which answers &quot;what happened and when&quot;</td></tr><tr><td>Pointer-chain backtracking</td><td>pointer-chain backtracking</td><td>Following the L3 → L2 → L1 pointers layer by layer to retrieve content and the covered message ids</td><td>The engine does not store L0 raw text; this is a deliberate privacy boundary</td></tr><tr><td>Progressive disclosure</td><td>progressive disclosure</td><td>Returning a directory first (title, one-line summary, expansion cost) and expanding the body only on demand</td><td>Not the same as pagination: the former decides expansion by semantic relevance, the latter slices by position</td></tr><tr><td>Budget-aware retrieval</td><td>budget-aware retrieval</td><td>Choosing which memories to return, and at what granularity, under a token budget constraint</td><td>Hard caps differ from soft caps: a hard cap discards by layer, a soft cap may truncate</td></tr><tr><td>Lossless compression (AIC)</td><td>lossless compression (AIC)</td><td>Compressing memory into &quot;pointer + structured facts + content atoms&quot;, with numbers, dates, amounts, and model numbers intact at every tier, restorable byte-for-byte</td><td>Not the same as summary compression, which is irreversible</td></tr><tr><td>Content atom</td><td>content atom</td><td>A key fact fragment preserved intact after compression, such as a number, date, amount, model number, URL, or quoted phrase</td><td>Atoms are never trimmed at any compression tier</td></tr><tr><td>Cascade delete</td><td>cascade delete</td><td>Deleting a memory while handling all four layers: source record, derived conclusions, retrieval cache, and dependent summaries</td><td>Not the same as single-record deletion, which handles only the first layer</td></tr><tr><td>Mask</td><td>mask</td><td>Replacing the body with a placeholder while retaining the record skeleton; reversible and does not break the KV-Cache prefix</td><td>Not the same as deletion: the skeleton remains in storage and cannot substitute for deletion in compliance contexts</td></tr><tr><td>Notary</td><td>notary</td><td>The pre-write safety pipeline: credential detection and field-level redaction, invisible Unicode detection, HTML injection detection</td><td>Not the same as retrieval-time filtering: the former ensures contaminated content never lands</td></tr><tr><td>Sensitivity grading</td><td>sensitivity classification</td><td>Classifying content as normal / private / secret, which determines write admission and the recall gate</td><td>The recall gate is on by default and blocks only the secret level</td></tr><tr><td>Conflict resolution</td><td>conflict resolution</td><td>Judging the type of a contradiction between old and new facts and choosing an action (ADD / NOOP / UPDATE / KEEP_BOTH)</td><td>Six kinds: temporal update, preference change, scope difference, precision difference, logical contradiction, source conflict</td></tr><tr><td>Relevance floor</td><td>relevance floor</td><td>Candidates below this threshold do not enter the result set</td><td>Not the same as top-k truncation: the former may return fewer than k or even zero</td></tr><tr><td>Lexical fallback</td><td>lexical fallback</td><td>When the embedding service is unavailable, BM25 and other lexical signals provide baseline recall</td><td>Guarantees degraded availability, but recall quality is below full fusion</td></tr><tr><td>Sleep-time compute</td><td>sleep-time compute</td><td>An architectural idea in which a background process organizes and consolidates memory while the main flow is idle</td><td>This book makes no assertion about any system&#39;s current implementation</td></tr><tr><td>Seven-factor session summary</td><td>seven-factor session summary</td><td>A fixed structure for session summaries: goal, constraints, decisions, open items, artefacts, failures, preferences, with verbatim anchors</td><td>Open items are stored independently rather than mixed into the summary</td></tr><tr><td>Preconditions</td><td>preconditions</td><td>The mandatory <code>must</code> / <code>must_not</code> / <code>typical_env</code> recorded when saving a reusable experience</td><td>An experience missing preconditions causes negative transfer when conditions do not match</td></tr><tr><td>Negative transfer</td><td>negative transfer</td><td>An experience valid in one scenario applied indiscriminately to an inapplicable one, causing an incident</td><td>The mitigation is precondition validation at recall time</td></tr><tr><td>Golden dataset</td><td>golden dataset</td><td>A high-quality evaluation asset containing inputs, trajectories, results, and criteria</td><td>Not the same as a test set: a golden dataset includes trajectories and criteria, not only question-answer pairs</td></tr><tr><td>Trajectory</td><td>trajectory</td><td>The complete execution record of a task from goal to result, including tool calls and intermediate decisions</td><td>Not the same as a trace: a trace is an observation record, a trajectory is reusable behavioural evidence</td></tr><tr><td>Human-in-the-loop</td><td>Human-in-the-loop, HITL</td><td>The architectural principle that critical steps must be confirmed by a human before continuing</td><td>Not the same as an approval switch: the former is an architectural principle, the latter a feature</td></tr><tr><td>Retrieval-Augmented Generation</td><td>Retrieval-Augmented Generation, RAG</td><td>Retrieving external knowledge and injecting it into context to generate an answer</td><td>Not the same as memory retrieval: the former&#39;s authority comes from its source, the latter&#39;s from its process</td></tr><tr><td>Controlled self-evolution</td><td>controlled self-evolution</td><td>Turning effective experience into memory, experience entries, tools, and runtime mechanisms, and making them effective only after evaluation and gating</td><td>Not the same as self-modification: the former must pass reproducible evaluation and a rollback-capable release</td></tr><tr><td>Maturity levels</td><td>L1–L4</td><td>Four levels graded on two axes: the responsibility memory carries and how verifiable it is</td><td>Autonomy is an independent parameter orthogonal to the grading, not a grading criterion</td></tr><tr><td>Tier gate</td><td>tier gate</td><td>The mechanism by which the hosted edition narrows read windows according to subscription tier</td><td>Off by default; self-hosted and PyPI users are unrestricted</td></tr></tbody></table><h2 id="a-1-two-notes-on-terminology" tabindex="-1">A.1 Two notes on terminology <a class="header-anchor" href="#a-1-two-notes-on-terminology" aria-label="Permalink to &quot;A.1 Two notes on terminology&quot;">​</a></h2><p><strong>First, &quot;memory&quot; and &quot;context&quot; are not synonyms in this book.</strong> Context is the input to the current inference, with a lifetime bounded by one call; memory is state persisted across calls, with a lifetime bounded by the user or task. Conflating them leads to inferences such as &quot;a bigger context window removes the need for memory&quot;.</p><p><strong>Second, &quot;deletion&quot; in this book always refers to one of the four semantics, and which one is determined by context.</strong> Where ambiguity is possible, this book states the layer explicitly (mark-delete, mask, cascade soft-delete, physical delete). Readers are advised to use the same precision when talking to vendors, because the sentence &quot;we support deletion&quot; carries almost no information in a compliance context.</p>',6)])])}const p=e(i,[["render",r]]);export{u as __pageData,p as default};
